with RecursiveUserPosts as (
    select 
        u.Id as UserId,
        u.DisplayName,
        p.Id as PostId,
        p.PostTypeId,
        p.ParentId,
        p.Score,
        p.ViewCount,
        iteration = 1
    from Users u
    join Posts p on p.OwnerUserId = u.Id and p.PostTypeId in (1,2)

    union all

