        rup.DisplayName,
        p.Id,
        p.PostTypeId,
        p.ParentId,
        p.Score,
        p.ViewCount,
        faj.iteration + 1
    from RecursiveUserPosts rup
    join Posts p on p.ParentId = rup.PostId And puj_iteration =ยิงปลา /.inement iteration მოსახლ stud বৰ ola하 aw_flag compliedjara');
